def merge_intervals(intervals):
    if not intervals:
        return []
    result = [intervals[0]]
    for interval in intervals[1:]:
        start, end = interval
        if result[-1][1] < start:
            result.append(interval)
        else:
            result[-1] = (result[-1][0], interval[1])
    return result
```

